INSERT INTO `raza` (`id_raza`, `nombre`, `descripcion`) VALUES (1,'Criollo','Raza autóctona sudamericana, resistente y de gran fortaleza.');
INSERT INTO `raza` (`id_raza`, `nombre`, `descripcion`) VALUES (2,'Pura Sangre de Carrera','Raza inglesa criada para velocidad en carreras.');
INSERT INTO `raza` (`id_raza`, `nombre`, `descripcion`) VALUES (3,'Cuarto de Milla','Raza estadounidense veloz en distancias cortas, usada en rodeo y trabajo de campo.');
INSERT INTO `raza` (`id_raza`, `nombre`, `descripcion`) VALUES (4,'Árabe','Una de las razas más antiguas, conocida por su resistencia y elegancia.');
INSERT INTO `raza` (`id_raza`, `nombre`, `descripcion`) VALUES (5,'Andaluz','Raza española de porte elegante, usada en doma clásica.');
INSERT INTO `raza` (`id_raza`, `nombre`, `descripcion`) VALUES (6,'Frisón','Raza holandesa de gran tamaño y capa negra, usada en espectáculos.');
INSERT INTO `raza` (`id_raza`, `nombre`, `descripcion`) VALUES (7,'Paso Fino','Raza con un andar suave y característico, originaria de Latinoamérica.');
INSERT INTO `raza` (`id_raza`, `nombre`, `descripcion`) VALUES (8,'Percherón','Raza francesa de tiro pesado, fuerte y de gran tamaño.');
INSERT INTO `raza` (`id_raza`, `nombre`, `descripcion`) VALUES (9,'Appaloosa','Raza estadounidense reconocida por su pelaje moteado.');
INSERT INTO `raza` (`id_raza`, `nombre`, `descripcion`) VALUES (10,'Mustang','Raza norteamericana descendiente de caballos españoles asilvestrados.');
